"""Download DPR authors' released NQ development data (not data generated by us).

Official author resource map:
https://github.com/facebookresearch/DPR/blob/main/dpr/data/download_data.py
"""
from __future__ import annotations
import argparse
from pathlib import Path
from urllib.request import urlretrieve

RESOURCES = {
    "nq-dev": "https://dl.fbaipublicfiles.com/dpr/data/retriever/biencoder-nq-dev.json.gz",
    "nq-train": "https://dl.fbaipublicfiles.com/dpr/data/retriever/biencoder-nq-train.json.gz",
    "nq-dev-qa": "https://dl.fbaipublicfiles.com/dpr/data/retriever/nq-dev.qa.csv",
    # Caution: very large; only download deliberately.
    "wikipedia-full": "https://dl.fbaipublicfiles.com/dpr/wikipedia_split/psgs_w100.tsv.gz",
}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--resource", choices=RESOURCES, default="nq-dev")
    parser.add_argument("--output-dir", default="data/raw")
    args = parser.parse_args()
    folder = Path(args.output_dir)
    folder.mkdir(parents=True, exist_ok=True)
    url = RESOURCES[args.resource]
    destination = folder / url.rsplit("/", 1)[-1]
    if destination.exists() and destination.stat().st_size:
        print("Already downloaded:", destination)
        return
    print("Downloading official DPR source:", url)
    try:
        urlretrieve(url, destination)
    except Exception:
        destination.unlink(missing_ok=True)
        raise
    print("Saved:", destination, "size:", destination.stat().st_size, "bytes")

if __name__ == "__main__":
    main()
